    let cart = JSON.parse\(localStorage.getItem\('novatech_cart'\) || '[]'\);

    function saveCart\(\) { localStorage.setItem\('novatech_cart', JSON.stringify\(cart\)\); }

    function updateCartDisplay\(\) {
      const total = cart.reduce\(\(s, i\) => s + i.qty, 0\);
      const countEl = document.getElementById\('cartCount'\);
      countEl.textContent = total;
      countEl.style.display = total > 0 ? 'flex' : 'none';

      const itemsEl = document.getElementById\('cartItems'\);
      const emptyEl = document.getElementById\('cartEmpty'\);
      const subtotalEl = document.getElementById\('cartSubtotal'\);
      const totalEl = document.getElementById\('cartTotal'\);

      if \(cart.length === 0\) {
        emptyEl.style.display = 'flex';
        subtotalEl.textContent = '£0.00';
        totalEl.textContent = '£0.00';
        // Remove all items except empty msg
        Array.from\(itemsEl.children\).forEach\(c => { if \(c !== emptyEl\) c.remove\(\); }\);
        return;
      }
      emptyEl.style.display = 'none';
      Array.from\(itemsEl.children\).forEach\(c => { if \(c !== emptyEl\) c.remove\(\); }\);

      let grandTotal = 0;
      cart.forEach\(item => {
        grandTotal += item.price * item.qty;
        const div = document.createElement\('div'\);
        div.className = 'cart-item';
        div.innerHTML = `
          <div class="cart-item-icon">${item.icon}</div>
          <div class="cart-item-info">
            <h4>${item.name}</h4>
            <p>£${\(item.price * item.qty\).toLocaleString\('en-GB', {minimumFractionDigits:2}\)}</p>
          </div>
          <div class="cart-item-controls">
            <button class="qty-btn" data-id="${item.id}" data-action="dec">−</button>
            <span class="qty-num">${item.qty}</span>
            <button class="qty-btn" data-id="${item.id}" data-action="inc">+</button>
            <button class="remove-btn" data-id="${item.id}" title="Remove">✕</button>
          </div>
        `;
        itemsEl.appendChild\(div\);
      }\);

      subtotalEl.textContent = `£${grandTotal.toLocaleString\('en-GB', {minimumFractionDigits:2}\)}`;
      totalEl.textContent = `£${grandTotal.toLocaleString\('en-GB', {minimumFractionDigits:2}\)}`;

      // Qty / remove events
      itemsEl.querySelectorAll\('.qty-btn'\).forEach\(btn => {
        btn.addEventListener\('click', \(\) => {
          const id = btn.dataset.id;
          const action = btn.dataset.action;
          const idx = cart.findIndex\(i => i.id === id\);
          if \(idx === -1\) return;
          if \(action === 'inc'\) cart[idx].qty++;
          else { cart[idx].qty--; if \(cart[idx].qty <= 0\) cart.splice\(idx, 1\); }
