          updateCartDisplay\(\);
        }\);
      }\);
      itemsEl.querySelectorAll\('.remove-btn'\).forEach\(btn => {
        btn.addEventListener\('click', \(\) => {
          const id = btn.dataset.id;
          cart = cart.filter\(i => i.id !== id\);
          saveCart\(\);
          updateCartDisplay\(\);
        }\);
      }\);
    }

    // Add to basket buttons
    document.querySelectorAll\('.btn-add'\).forEach\(btn => {
