      top: 34px;
      left: 15%;
      right: 15%;
      height: 1px;
      background: linear-gradient\(to right, transparent, var\(--accent\), transparent\);
      opacity: 0.3;
      z-index: 0;
    }
    .hiw-step {
      text-align: center;
      position: relative;
      z-index: 1;
    }
    .step-num {
      width: 68px;
      height: 68px;
      background: var\(--card\);
