      margin-bottom: 6px;
    }
    .hiw-step p { font-size: 0.8rem; color: var\(--grey\); }

    /* ── BOOKING FORM ── */
    .booking-section {
      position: relative;
      z-index: 1;
      padding: 80px 24px;
    }
    .booking-inner {
      max-width: 760px;
      margin: 0 auto;
      background: var\(--card\);
      border: 1px solid var\(--border\);
      border-radius: 24px;
      padding: 52px 48px;
    }

    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .form-group { margin-bottom: 18px; }
    .form-group label {
      display: block;
      font-size: 0.78rem;
      font-weight: 600;
      color: var\(--grey\);
      margin-bottom: 8px;
      letter-spacing: 0.3px;
      text-transform: uppercase;
    }
    .form-group input,
    .form-group select,
    .form-group textarea {
