  <script>
    const hamburgerBtn = document.getElementById\('hamburgerBtn'\);
    const mobileMenu = document.getElementById\('mobileMenu'\);
    hamburgerBtn.addEventListener\('click', \(\) => mobileMenu.classList.toggle\('open'\)\);
    document.addEventListener\('click', \(e\) => {
      if \(!hamburgerBtn.contains\(e.target\) && !mobileMenu.contains\(e.target\)\)
        mobileMenu.classList.remove\('open'\);
    }\);

    // Cart sync
    function updateCartDisplay\(\) {
      const cart = JSON.parse\(localStorage.getItem\('novatech_cart'\) || '[]'\);
      const total = cart.reduce\(\(s, i\) => s + i.qty, 0\);
      const el = document.getElementById\('cartCount'\);
      if \(el\) { el.textContent = total; el.style.display = total > 0 ? 'flex' : 'none'; }
    }
    updateCartDisplay\(\);
    window.addEventListener\('storage', updateCartDisplay\);

    // Set min date to today for date picker
    const dateInput = document.getElementById\('rdate'\);
    if \(dateInput\) {
      const today = new Date\(\).toISOString\(\).split\('T'\)[0];
      dateInput.min = today;
    }

    // Repair form submit
    const repairForm = document.getElementById\('repairForm'\);
    const repairSuccess = document.getElementById\('repairSuccess'\);
    repairForm.addEventListener\('submit', \(e\) => {
      e.preventDefault\(\);
      repairForm.style.display = 'none';
      repairSuccess.style.display = 'block';
    }\);

    // Smooth scroll for all "Book Now" anchor links
    document.querySelectorAll\('a[href="#bookingForm"]'\).forEach\(link => {
      link.addEventListener\('click', \(e\) => {
        e.preventDefault\(\);
        const target = document.getElementById\('bookingForm'\);
        if \(target\) {
          target.scrollIntoView\({ behavior: 'smooth', block: 'start' }\);
        }
      }\);
    }\);
  </script>
